import json
import time
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen

BASE = 'http://localhost:8080'
START = datetime(2025, 3, 1, tzinfo=timezone.utc)
END = datetime(2025, 6, 1, tzinfo=timezone.utc)


def parse_dt(s):
    return datetime.fromisoformat(s.replace('Z', '+00:00')).astimezone(timezone.utc)


def wait_seconds(headers, body):
    value = headers.get('Retry-After') or headers.get('retry-after')
    if value:
        try:
            return max(0.0, float(value))
        except ValueError:
            pass
    if isinstance(body, dict):
        for key in ('retry_after', 'retry-after', 'wait_seconds', 'wait'):
            if key in body:
                try:
                    return max(0.0, float(body[key]))
                except (TypeError, ValueError):
                    pass
    return 1.0


def request_json(path, method='GET', token=None):
    global_token = token
    attempts = 0
    while True:
        attempts += 1
        headers = {'Accept': 'application/json'}
        if global_token:
            headers['Authorization'] = 'Bearer ' + global_token
        req = Request(BASE + path, method=method, headers=headers)
        try:
            with urlopen(req, timeout=30) as response:
                raw = response.read()
                return json.loads(raw.decode('utf-8')), global_token
        except HTTPError as exc:
            raw = exc.read()
            try:
                body = json.loads(raw.decode('utf-8')) if raw else {}
            except Exception:
                body = {}
            if exc.code == 401 and token is not None:
                # Signal to caller that its token must be refreshed.
                return {'__auth_expired__': True}, global_token
            if exc.code == 429:
                delay = wait_seconds(exc.headers, body)
                print(f'Rate limited on {path}; waiting {delay:g}s', flush=True)
                time.sleep(delay)
                continue
            if exc.code >= 500 or exc.code in (408, 425):
                delay = min(30.0, max(1.0, 2 ** min(attempts - 1, 5)))
                print(f'Request failed ({exc.code}) on {path}; retrying in {delay:g}s', flush=True)
                time.sleep(delay)
                continue
            raise RuntimeError(f'HTTP {exc.code} for {path}: {body"'!r}'"')
        except (URLError, TimeoutError) as exc:
            delay = min(30.0, max(1.0, 2 ** min(attempts - 1, 5)))
            print(f'Request error on {path}: {exc}; retrying in {delay:g}s', flush=True)
            time.sleep(delay)


def new_token():
    data, _ = request_json('/token', method='POST')
    if not isinstance(data, dict) or not data.get('token'):
        raise RuntimeError(f'Invalid token response: {data"'!r}'"')
    return data['token']


token = [REDACTED_SECRET]
seen = set()
duplicates_skipped = 0
all_orders = []
path = '/orders?page=1'
page_count = 0
while path:
    page_count += 1
    while True:
        data, _ = request_json(path, token=token)
        if data.get('__auth_expired__'):
            token = [REDACTED_SECRET]
            continue
        break
    if not isinstance(data, dict) or not isinstance(data.get('items'), list):
        raise RuntimeError(f'Invalid orders response for {path}: {data"'!r}'"')
    for order in data['items']:
        oid = order.get('id')
        if oid in seen:
            duplicates_skipped += 1
            continue
        seen.add(oid)
        all_orders.append(order)
    print(f'Fetched page {page_count}/{data.get(\"total_pages\", \"?\")}: {len(data[\"items\"])} listings', flush=True)
    next_path = data.get('next')
    if next_path is not None and not isinstance(next_path, str):
        raise RuntimeError(f'Invalid next cursor: {next_path"'!r}'"')
    path = next_path

customer_cache = {}
qualifying = []
for order in all_orders:
    if order.get('status') "'!= '"'shipped':
        continue
    placed = parse_dt(order['placed_at'])
    if not (START <= placed < END):
        continue
    cid = order['customer_id']
    if cid not in customer_cache:
        cpath = '/customers/' + str(cid)
        while True:
            customer, _ = request_json(cpath, token=token)
            if customer.get('__auth_expired__'):
                token = [REDACTED_SECRET]
                continue
            break
        customer_cache[cid] = customer
    customer = customer_cache[cid]
    if not isinstance(customer, dict) or 'discount_pct' not in customer or 'region' not in customer:
        raise RuntimeError(f'Invalid customer response for {cid}: {customer"'!r}'"')
    qualifying.append((order, customer))

by_region = {'north': 0, 'south': 0, 'east': 0, 'west': 0}
for order, customer in qualifying:
    amount = Decimal(str(order['amount_cents']))
    discount = Decimal(str(customer['discount_pct']))
    discounted = (amount * (Decimal(100) - discount) / Decimal(100)).quantize(Decimal('1'), rounding=ROUND_HALF_UP)
    cents = int(discounted)
    region = customer['region']
    if region not in by_region:
        raise RuntimeError(f'Unexpected region: {region"'!r}'"')
    by_region[region] += cents

result = {
    'total_cents': sum(by_region.values()),
    'order_count': len(qualifying),
    'duplicates_skipped': duplicates_skipped,
    'by_region': by_region,
}
if sum(by_region.values()) "'!= result['"'total_cents']:
    raise RuntimeError('Region total mismatch')
print(json.dumps(result, sort_keys=True))
